/* WAPILLAR(r, key): challenge passes when that pillar has no findings left */
window.WAPILLAR = function (r, k, extra) {
  if (!r.ok) return 'the review must run: ' + r.error;
  const left = r.findings.filter(f => f.pillar === k);
  if (left.length) return `${r.pillars[k].name} still has ${left.length} finding(s): ${left.map(f => f.id).join(', ')}`;
  return extra ? extra(r) : true;
};
window.WA_PILLAR_SCENE = (center, items, color) => ({ type: 'graph', nodes: [
  { id: 'p', x: 470, y: 240, icon: center[0], label: center[1], sub: center[2] }
].concat(items.map((it, i) => ({ id: it[0], x: [130, 470, 810, 810, 470, 130][i], y: [100, 60, 100, 380, 420, 380][i], icon: it[1], label: it[2], sub: it[3], at: it[4] }))),
  edges: items.map(it => ({ a: 'p', b: it[0], at: it[4] })) });

/* ============ 10 OPERATIONAL EXCELLENCE ============ */
