/* reveal each pillar-diagram node no later than the first step that points at it */
LESSONS.filter(l => l.cat === 'pil').forEach(l => (l.scene.nodes || []).forEach(n => {
  const first = l.steps.findIndex(s => (s.focus || []).includes(n.id) || (s.flow && (s.flow.from === n.id || s.flow.to === n.id)));
  if (first >= 0 && (n.at == null || n.at > first)) { n.at = first || undefined; (l.scene.edges || []).forEach(e => { if (e.b === n.id) e.at = n.at; }); }
}));
